<script setup lang="ts">
import BundlePricing from '@/components/BundlePricing.vue'
import { computed,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { request } from '@/api/http'
import { useAuthStore } from '@/stores/auth'

type Terms={schemaVersion:2;model:'subscription';intervalMonths:1|3|12|24;available:boolean;trial:{enabled:boolean;days:number};renewal:'manual'}
type Expense={label:string;category:'supplier'|'infrastructure'|'risk';quantity:string;unitSize:string;unitRate:string;currency:'CNY'|'USD';fxToCny:string}
type Ai={currency:'CNY'|'USD';fxToCny:string;inputTokens:string;cachedInputTokens:string;cacheWriteTokens:string;outputTokens:string;inputPerMillion:string;cachedPerMillion:string;cacheWritePerMillion:string;outputPerMillion:string;requests:string;requestFee:string}
type Scenario={retailPrice:string;salesVolume:string;monthlyFixedCost:string;supportMinutes:string;supportHourlyCost:string;paymentFixedFee:string;paymentFeeBps:number;taxReserveBps:number;refundReserveBps:number;targetMarginBps:number;expenses:Expense[];ai?:Ai}
type Version={priceVersionId:string;revision:number;label:string;billingType:string;unit:string;price:string;terms?:Terms;scenario:Scenario;validUntil:number;evidenceNote:string;assessment:{eligibleForSale:boolean;reviewRequired:string|null}}
type History={revision:number;publishedPriceId:string|null;versions:Version[]}
type PeriodPlan={id:string;months:1|3|12|24;label:string;unit:string;planCode:string;history:History}
type Product={application:string;name:string;priceProductCode:string;plans:PeriodPlan[]}
type Contract={bundleQuoteId?:string;discountMinor?:string;grantId:string;application:string;customerId:string;customerName:string;intervalMonths:number;amountMinor:string;currency:string;periodStart:number;periodEnd:number;status:string}
type Calculation={directCost:string;contributionRounded:string;contributionMarginPercent:string|null;estimatedMonthlyOperatingProfit:string;monthlyRevenue:string;breakEvenSales:string|null;aiCost:string;labor:string;revenueReserve:string;lossMaking:boolean;meetsTarget:boolean}
type Reply<T>={data:T}
const auth=useAuthStore(),route=useRoute(),base='/platform/pricing'
const emit=defineEmits<{ 'application-context-change':[context:{selectedCode:string;selectedLabel:string;options:Array<{code:string;name:string;statusText:string}>}] }>()
const selectedMonths=ref<1|3|12|24>(1),contracts=ref<Contract[]>([]),contractPage=ref(1),contractTotal=ref(0),contractError=ref('')
const products=ref<Product[]>([]),selected=ref(''),loading=ref(false),busy=ref(false),message=ref(''),error=ref('')
const form=reactive({price:'',available:true,trialEnabled:false,trialDays:30,unit:'',label:'',evidenceDays:30,evidenceNote:'',salesVolume:'0',monthlyFixedCost:'0',supportMinutes:'0',supportHourlyCost:'0',paymentFixedFee:'0',paymentPercent:'0',taxPercent:'0',refundPercent:'0',targetPercent:'60'})
const expenses=ref<Expense[]>([]),includeAi=ref(false)
const ai=reactive<Ai>({currency:'CNY',fxToCny:'1',inputTokens:'0',cachedInputTokens:'0',cacheWriteTokens:'0',outputTokens:'0',inputPerMillion:'0',cachedPerMillion:'0',cacheWritePerMillion:'0',outputPerMillion:'0',requests:'0',requestFee:'0'})
const aiFields:Array<{key:Exclude<keyof Ai,'currency'|'fxToCny'>;label:string}>=[{key:'inputTokens',label:'输入总 token 数'},{key:'cachedInputTokens',label:'其中缓存命中 token'},{key:'cacheWriteTokens',label:'其中缓存写入 token'},{key:'outputTokens',label:'输出 token 数'},{key:'inputPerMillion',label:'未缓存输入 / 百万 token'},{key:'cachedPerMillion',label:'缓存命中 / 百万 token'},{key:'cacheWritePerMillion',label:'缓存写入 / 百万 token'},{key:'outputPerMillion',label:'输出 / 百万 token'},{key:'requests',label:'请求次数'},{key:'requestFee',label:'每次请求固定费'}]
const calculation=ref<Calculation|null>(null),calculating=ref(false),publication=ref<Version|null>(null),publicationNote=ref(''),confirmed=ref(false)
const product=computed(()=>products.value.find(row=>row.priceProductCode===selected.value))
const plan=computed(()=>product.value?.plans.find(row=>row.months===selectedMonths.value))
const history=computed(()=>plan.value?.history ?? {revision:0,publishedPriceId:null,versions:[]})
const published=computed(()=>history.value.versions.find(row=>row.priceVersionId===history.value.publishedPriceId))
const canWrite=computed(()=>auth.permissions.includes('pricing:write')),canPublish=computed(()=>auth.permissions.includes('pricing:publish'))
const displayPrice=(value:string)=>'¥'+value
function periodText(months:number){return ({1:'月付',3:'季付',12:'年付',24:'两年付'} as Record<number,string>)[months] ?? ''}
function termsText(value?:Terms){return !value?'订阅待配置':periodText(value.intervalMonths)+' · '+(value.available?'可购买':'已停售')}
function current(row:PeriodPlan){return row.history.versions.find(v=>v.priceVersionId===row.history.publishedPriceId)}
function date(value:number){return new Date(Number(value)).toLocaleString()}
function amount(value:string){return '¥'+String(BigInt(value)/100n)+'.'+String(BigInt(value)%100n).padStart(2,'0')}
function trialText(value?:Terms){return value?.trial.enabled?`${value.trial.days}天免费试用`:'未提供免费试用'}
function bps(value:string){if(!/^(0|[1-9]\d{0,2})(\.\d{1,2})?$/.test(value))throw new Error('百分比最多填写两位小数');return Math.round(Number(value)*100)}
function scenario():Scenario{return {retailPrice:form.price.trim(),salesVolume:form.salesVolume,monthlyFixedCost:form.monthlyFixedCost,supportMinutes:form.supportMinutes,supportHourlyCost:form.supportHourlyCost,paymentFixedFee:form.paymentFixedFee,paymentFeeBps:bps(form.paymentPercent),taxReserveBps:bps(form.taxPercent),refundReserveBps:bps(form.refundPercent),targetMarginBps:bps(form.targetPercent),expenses:expenses.value.map(line=>({...line})),...(includeAi.value?{ai:JSON.parse(JSON.stringify(ai))}:{})}}
let controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,generation=0
let savedAttempt:{payload:Record<string,unknown>}|undefined,publishAttempt:{payload:Record<string,unknown>}|undefined
async function calculate(){
  controller?.abort();const own=new AbortController();controller=own;calculating.value=true
  try{const result=await request.post<Reply<Calculation>>(base+'/calculate',scenario(),{signal:own.signal});if(!own.signal.aborted){calculation.value=result.data;error.value=''}}
  catch(e){if(!own.signal.aborted){calculation.value=null;error.value=e instanceof Error?e.message:'测算暂不可用'}}
  finally{if(controller===own)calculating.value=false}
}
function announce(){emit('application-context-change',{selectedCode:product.value?.application ?? 'all',selectedLabel:product.value?.name ?? '全部应用',options:products.value.map(row=>({code:row.application,name:row.name,statusText:'定价管理'}))})}
function resetEditor(){
  controller?.abort();calculation.value=null;error.value='';message.value='';savedAttempt=undefined
  Object.assign(form,{price:'',available:true,trialEnabled:false,trialDays:30,unit:plan.value?.unit ?? '',label:product.value?.name ?? '',evidenceNote:'',evidenceDays:30,salesVolume:'0',monthlyFixedCost:'0',supportMinutes:'0',supportHourlyCost:'0',paymentFixedFee:'0',paymentPercent:'0',taxPercent:'0',refundPercent:'0',targetPercent:'60'})
  Object.assign(ai,{currency:'CNY',fxToCny:'1',inputTokens:'0',cachedInputTokens:'0',cacheWriteTokens:'0',outputTokens:'0',inputPerMillion:'0',cachedPerMillion:'0',cacheWritePerMillion:'0',outputPerMillion:'0',requests:'0',requestFee:'0'})
  expenses.value=[];includeAi.value=false;announce()
  if(published.value)loadRevision(published.value)
}
function loadRevision(row:Version){
  const c=row.scenario
  Object.assign(form,{price:row.price,available:row.terms?.available ?? true,trialEnabled:row.terms?.trial.enabled ?? false,trialDays:row.terms?.trial.enabled?row.terms.trial.days:30,unit:row.unit,label:row.label,evidenceNote:row.evidenceNote,salesVolume:c.salesVolume,monthlyFixedCost:c.monthlyFixedCost,supportMinutes:c.supportMinutes,supportHourlyCost:c.supportHourlyCost,paymentFixedFee:c.paymentFixedFee,paymentPercent:String(c.paymentFeeBps/100),taxPercent:String(c.taxReserveBps/100),refundPercent:String(c.refundReserveBps/100),targetPercent:String(c.targetMarginBps/100)})
  expenses.value=JSON.parse(JSON.stringify(c.expenses));includeAi.value=Boolean(c.ai);if(c.ai)Object.assign(ai,c.ai)
  message.value=`已载入价格修订 ${row.revision}；编辑不会改变当前发布方案。`
}
async function refresh(){
  const own=++generation;loading.value=true
  try{const result=await request.get<Reply<{products:Product[]}>>(base+'/products');if(own!==generation)return;products.value=result.data.products;if(!products.value.some(row=>row.priceProductCode===selected.value))selected.value=products.value[0]?.priceProductCode ?? '';announce()}
  catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{if(own===generation)loading.value=false}
}
async function save(review=false){
  if(!product.value)return;busy.value=true;error.value=''
  try{
    const terms:Terms={schemaVersion:2,model:'subscription',intervalMonths:selectedMonths.value,available:form.available,trial:{enabled:form.trialEnabled,days:form.trialEnabled?Number(form.trialDays):0},renewal:'manual'}
    savedAttempt ??={payload:{productCode:selected.value,label:form.label,billingType:'subscription',unit:form.unit,price:form.price.trim(),terms,expectedRevision:history.value.revision,scenario:scenario(),validUntil:Date.now()+Number(form.evidenceDays)*86400000,evidenceNote:form.evidenceNote,idempotencyKey:crypto.randomUUID()}}
    const saved=await request.post<Reply<{priceVersionId:string}>>(base+'/versions',savedAttempt.payload);savedAttempt=undefined;await refresh();message.value='草稿已保存，尚未生效。需要确认发布。';if(review){const row=history.value.versions.find(v=>v.priceVersionId===saved.data.priceVersionId);if(row)openPublication(row)}
  }catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}
}
async function publish(){
  if(!publication.value)return;busy.value=true;error.value=''
  try{publishAttempt ??={payload:{intervalMonths:selectedMonths.value,priceVersionId:publication.value.priceVersionId,expectedPublishedId:history.value.publishedPriceId,note:publicationNote.value,idempotencyKey:crypto.randomUUID()}};const accepted=publication.value;await request.post(base+'/products/'+encodeURIComponent(selected.value)+'/publish',publishAttempt.payload);publication.value=null;publishAttempt=undefined;await refresh();loadRevision(accepted);message.value='已确认发布并生效。已支付用户的价格与到期日保持不变。'}catch(e){error.value=e instanceof Error?e.message:'发布失败'}finally{busy.value=false}
}
function openPublication(row:Version){publication.value=row;publicationNote.value='';confirmed.value=false;publishAttempt=undefined}
let withdrawAttempt:Record<string,unknown>|undefined
async function prepareWithdrawal(){
 if(!published.value)return;busy.value=true;error.value=''
 try{withdrawAttempt ??={intervalMonths:selectedMonths.value,expectedPublishedId:history.value.publishedPriceId,expectedRevision:history.value.revision,idempotencyKey:crypto.randomUUID()};const result=await request.post<Reply<{priceVersionId:string}>>(base+'/products/'+encodeURIComponent(selected.value)+'/withdrawal-draft',withdrawAttempt);withdrawAttempt=undefined;await refresh();const row=history.value.versions.find(v=>v.priceVersionId===result.data.priceVersionId);if(row)openPublication(row)}catch(e){error.value=e instanceof Error?e.message:'停售草稿保存失败'}finally{busy.value=false}
}
let contractGeneration=0
async function loadContracts(){if(!product.value)return;const app=product.value.application,own=++contractGeneration;contractError.value='';try{const result=await request.get<Reply<{rows:Contract[];total:number}>>(base+'/contracts',{params:{application:app,page:contractPage.value,pageSize:20}});if(own!==contractGeneration || product.value?.application!==app)return;contracts.value=result.data.rows;contractTotal.value=result.data.total}catch{if(own!==contractGeneration)return;contractError.value='客户订阅记录暂不可用'}}
function addExpense(){if(expenses.value.length<12)expenses.value.push({label:'',category:'infrastructure',quantity:'1',unitSize:'1',unitRate:'0',currency:'CNY',fxToCny:'1'})}
watch(selected,()=>{withdrawAttempt=undefined;selectedMonths.value=1;resetEditor();contracts.value=[];contractTotal.value=0;contractPage.value=1;void loadContracts()})
watch(selectedMonths,()=>{withdrawAttempt=undefined;resetEditor()})
watch(contractPage,()=>void loadContracts())
watch(()=>JSON.stringify([form,expenses.value,includeAi.value,ai]),()=>{savedAttempt=undefined;if(timer)clearTimeout(timer);controller?.abort();calculation.value=null;if(form.price.trim())timer=setTimeout(()=>void calculate(),400)})
watch(publicationNote,()=>{publishAttempt=undefined})
onMounted(async()=>{await refresh();const candidate=typeof route.query.product==='string'?route.query.product:new URLSearchParams(route.hash.slice(1)).get('product');if(candidate&&products.value.some(row=>row.priceProductCode===candidate))selected.value=candidate;if(product.value&&!form.label)resetEditor()})
onBeforeUnmount(()=>{contractGeneration++;controller?.abort();if(timer)clearTimeout(timer);generation++})
</script>

<template>
  <main class="pricing-page">
    <header class="page-head"><div><h2>定价与收费方案</h2><p>统一测算成本、选择收费方式与试用规则，再发布到对应应用。</p></div><button class="secondary" :disabled="loading || busy" @click="refresh">刷新方案</button></header>
    <p v-if="error" role="alert" class="notice error">{{ error }}</p><p v-if="message" role="status" class="notice success">{{ message }}</p>
    <section class="card product-picker"><label>管理产品<select aria-label="管理产品" v-model="selected" :disabled="loading || busy"><option v-for="row in products" :key="row.priceProductCode" :value="row.priceProductCode">{{ row.name }}</option></select></label><span class="pill">{{ published ? '已有发布方案':'尚未定价' }}</span></section>
    <section class="plan-grid" aria-label="付款周期方案"><button v-for="row in product?.plans" :key="row.id" class="card plan-choice" :class="{chosen:selectedMonths===row.months}" :aria-pressed="selectedMonths===row.months" :disabled="busy || loading" @click="selectedMonths=row.months"><strong>{{ row.label }}</strong><span>{{ row.months }}个月使用权</span><b>{{ current(row)?.price ? displayPrice(current(row)!.price):'售价待定' }}</b><small>{{ !current(row)?'尚未发布':current(row)?.terms?.available?'已发布 · 可购买':'已停售' }}</small></button></section>
    <section class="action-bar card"><p><strong>{{ periodText(selectedMonths) }} · 编辑不会立即生效</strong><br/><small>先保存草稿，再审核并确认发布。停售也需要确认，且保留已支付权益。</small></p><div><button class="secondary" :disabled="busy || !calculation || !canWrite" @click="save(false)">仅保存草稿</button><button class="primary" :disabled="busy || !calculation || !canWrite || !canPublish" @click="save(true)">审核并发布价格</button><button v-if="published?.terms?.available" class="secondary danger" :disabled="busy || !canWrite || !canPublish" @click="prepareWithdrawal">停售此周期方案</button></div></section>
    <div class="policy-grid">
      <section class="card"><h3>{{ periodText(selectedMonths) }}候选方案 · {{ selectedMonths }}个月总价</h3><div class="fields">
        <label>产品名称<input v-model="form.label" /></label><label>本周期总价（人民币）<input v-model="form.price" inputmode="decimal" placeholder="尚未决定，请输入候选售价" /></label>
        <label>付款周期<input :value="periodText(selectedMonths)+' · '+selectedMonths+'个月'" readonly /></label><label class="check"><input v-model="form.available" type="checkbox" />发布后允许购买此方案</label>
        <label class="check"><input v-model="form.trialEnabled" type="checkbox" />启用免费试用</label><label v-if="form.trialEnabled">免费试用天数<input v-model.number="form.trialDays" type="number" min="1" max="365" /></label>
      </div><p class="muted">订阅按1、3、12或24个日历月提供使用权，按完整周期付款并主动续费。试用不自动扣款。已支付用户保留原价和已付期限；停售仅影响新购买。</p></section>
      <section class="card preview"><h3>用户展示预览 · 尚未发布</h3><strong class="candidate">{{ form.price ? displayPrice(form.price):'售价待定' }}</strong><p>{{ periodText(selectedMonths) }} · {{ selectedMonths }}个月总价 · {{ form.available?'发布后可购买':'发布后停售' }}</p><p>{{ form.trialEnabled?`${form.trialDays}天免费试用`:'免费试用未开启' }}</p><hr/><h4>当前已发布</h4><template v-if="published"><p><strong>{{ displayPrice(published.price) }}</strong> / {{ published.unit }}</p><p>{{ termsText(published.terms) }} · {{ trialText(published.terms) }}</p><p>价格修订 {{ published.revision }} · {{ published.assessment.eligibleForSale?'成本审核可用':'成本需复核' }}</p></template><p v-else>该产品尚未发布售价或收费规则。</p><p class="muted">收款接入尚未启用。发布参考方案不会扣款，也不会将钱包余额或注册状态变成购买权益。</p></section>
    </div>
    <section class="card"><h3>定价与利润测算</h3><p class="muted">沿用现有后端精确金额测算。按整个所选订阅周期填写单份合同的成本；例如年付成本覆盖12个月，试用成本也应计入费用。经营利润是按新增合同销量估算的现金贡献，不是月度经常性收入。下列数值是您输入的假设，不是实际收入或供应商报价。</p>
      <div class="fields"><label>每月销量 / 付费单位数<input v-model="form.salesVolume" inputmode="decimal" /></label><label>每月固定费用（元）<input v-model="form.monthlyFixedCost" inputmode="decimal" /></label><label>每个收费单位支持分钟数<input v-model="form.supportMinutes" inputmode="decimal" /></label><label>支持人力小时成本（元）<input v-model="form.supportHourlyCost" inputmode="decimal" /></label><label>每笔固定支付费（元）<input v-model="form.paymentFixedFee" inputmode="decimal" /></label><label>支付费率（%）<input v-model="form.paymentPercent" inputmode="decimal" /></label><label>税费预留（%）<input v-model="form.taxPercent" inputmode="decimal" /></label><label>退款 / 风险预留（%）<input v-model="form.refundPercent" inputmode="decimal" /></label><label>目标贡献毛利率（%）<input v-model="form.targetPercent" inputmode="decimal" /></label></div>
      <div class="subhead"><h4>供应商、计算、存储与试用费用</h4><button class="secondary" :disabled="expenses.length>=12" @click="addExpense">添加费用</button></div>
      <div v-for="(line,index) in expenses" :key="index" class="expense"><label>费用名称 {{ index+1 }}<input v-model="line.label" /></label><label>费用类别<select aria-label="费用类别" v-model="line.category"><option value="supplier">供应商</option><option value="infrastructure">基础设施</option><option value="risk">其他风险成本</option></select></label><label>数量<input v-model="line.quantity" inputmode="decimal" /></label><label>报价单位大小<input v-model="line.unitSize" inputmode="decimal" /></label><label>单价<input v-model="line.unitRate" inputmode="decimal" /></label><label>币种<select aria-label="币种" v-model="line.currency" @change="line.fxToCny=line.currency==='CNY'?'1':''"><option>CNY</option><option>USD</option></select></label><label>折合人民币汇率<input v-model="line.fxToCny" inputmode="decimal" /></label><button class="text" @click="expenses.splice(index,1)">移除费用</button></div>
      <label class="check"><input v-model="includeAi" type="checkbox" />计入 AI API 成本</label>
      <div v-if="includeAi" class="fields ai"><label>AI 报价币种<select aria-label="AI 报价币种" v-model="ai.currency" @change="ai.fxToCny=ai.currency==='CNY'?'1':''"><option>CNY</option><option>USD</option></select></label><label>AI 汇率<input v-model="ai.fxToCny" inputmode="decimal" /></label><label v-for="item in aiFields" :key="item.key">{{ item.label }}<input v-model="ai[item.key]" inputmode="decimal" /></label></div>
      <button class="primary" :disabled="!form.price || calculating" @click="calculate">{{ calculating?'后端测算中…':'重新测算' }}</button>
      <div v-if="calculation" class="results" aria-label="后端测算结果"><article><span>单位直接成本</span><strong>{{ displayPrice(calculation.directCost) }}</strong></article><article><span>单位贡献利润</span><strong>{{ displayPrice(calculation.contributionRounded) }}</strong></article><article><span>贡献毛利率</span><strong>{{ calculation.contributionMarginPercent ?? '—' }}%</strong></article><article><span>预计每月经营利润</span><strong>{{ displayPrice(calculation.estimatedMonthlyOperatingProfit) }}</strong></article><article><span>每月收入估算</span><strong>{{ displayPrice(calculation.monthlyRevenue) }}</strong></article><article><span>盈亏平衡销量</span><strong>{{ calculation.breakEvenSales ?? '无法覆盖固定成本' }}</strong></article></div>
      <p v-if="calculation?.lossMaking || calculation && !calculation.meetsTarget" class="notice warning">候选售价尚未覆盖成本或达到目标贡献毛利率，请复核。</p>
    </section>
    <section class="card"><h3>保存与发布</h3><div class="fields"><label>成本证据有效天数<input v-model.number="form.evidenceDays" type="number" min="1" max="366" /></label><label class="wide">成本来源、日期、币种及判断依据<textarea v-model="form.evidenceNote" placeholder="至少10个字符；请说明人力、供应商与试用成本假设" /></label></div><button class="primary" :disabled="!canWrite || busy || !calculation" @click="save(false)">保存新方案草稿</button><p class="muted">草稿不会改变用户看到的方案。发布仅影响之后接受的新合同；既有购买、已付月份与已开始的试用不会被改写。</p></section>
    <section class="card history"><h3>价格修订与发布记录</h3><p v-if="!history.versions.length" class="muted">此周期尚无价格修订。输入并确认发布后才会生效；其他周期独立管理。</p><table v-else><thead><tr><th>修订</th><th>价格与方式</th><th>试用</th><th>审核与状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in history.versions" :key="row.priceVersionId"><td>{{ row.revision }}</td><td>{{ displayPrice(row.price) }} / {{ row.unit }}<small>{{ termsText(row.terms) }}</small></td><td>{{ trialText(row.terms) }}</td><td>{{ row.priceVersionId===history.publishedPriceId?'当前已发布':'历史 / 草稿' }}<small>{{ row.assessment.reviewRequired ?? '成本审核可用' }}</small></td><td><button class="text" @click="loadRevision(row)">载入编辑</button><button class="secondary" :disabled="!canPublish || busy || !row.terms || row.priceVersionId===history.publishedPriceId" @click="openPublication(row)">发布此方案</button></td></tr></tbody></table></section>
    <section class="card history"><h3>客户订阅记录</h3><p class="muted">每条记录关联公司用户、应用、已购买付款周期、成交金额和独立到期日。停售与改价不会改写这些记录。</p><p v-if="contractError" role="alert">{{ contractError }}</p><p v-else-if="!contracts.length">尚无已支付的订阅记录。</p><table v-else><thead><tr><th>客户</th><th>付款周期 / 金额</th><th>有效期</th><th>状态</th></tr></thead><tbody><tr v-for="row in contracts" :key="row.grantId"><td>{{ row.customerName }}<small>客户 #{{ row.customerId }}</small></td><td>{{ periodText(row.intervalMonths) }} / {{ amount(row.amountMinor) }}<small v-if="row.bundleQuoteId">组合报价 {{row.bundleQuoteId}} · 优惠 {{amount(row.discountMinor??'0')}}</small></td><td>{{ date(row.periodStart) }}<small>至 {{ date(row.periodEnd) }}</small></td><td>{{ row.status==='refunded'?'已退款':Date.now()<Number(row.periodStart)?'待生效':Date.now()<Number(row.periodEnd)?'有效':'已到期' }}</td></tr></tbody></table><div class="pager"><button class="secondary" :disabled="contractPage<=1" @click="contractPage--">上一页</button><span>第{{ contractPage }}页 / 共{{ contractTotal }}条</span><button class="secondary" :disabled="contractPage*20>=contractTotal" @click="contractPage++">下一页</button></div></section>
    <div v-if="publication" class="modal-mask"><section role="dialog" aria-modal="true" aria-label="确认发布方案" class="modal card"><h3>{{ publication.terms?.available?'确认发布价格':'确认停售方案' }}</h3><p>{{ product?.name }} · {{ displayPrice(publication.price) }} / {{ publication.unit }}</p><p>{{ termsText(publication.terms) }} · {{ trialText(publication.terms) }}</p><p v-if="!publication.assessment.eligibleForSale" class="notice warning">成本审核未通过或已过期。可发布参考展示，但试用与购买报价将被后端阻止。</p><p>生效范围：所选应用及付款周期的新购买。不会改写已有客户的已支付金额和使用到期日；不会启用收款或自动续费。</p><label>发布原因<textarea v-model="publicationNote" placeholder="至少5个字符" /></label><label class="check"><input v-model="confirmed" type="checkbox" />我已核对应用、付款周期、总价和可购买状态</label><footer><button class="secondary" :disabled="busy" @click="publication=null">取消</button><button class="primary" :disabled="busy || !confirmed || publicationNote.trim().length<5" @click="publish">{{ publication.terms?.available?'确认发布价格并生效':'确认停售并生效' }}</button></footer></section></div>
  <BundlePricing :products="products"/>
</main>
</template>

